SELECT *
FROM Learn
WHERE user_id = #{userId}
AND course_id = #{courseId}
LIMIT 1

select Learn.*, Course.name as courseName, Course.course_code as courseCode,Course.instructor_name as instructorName, Course.school as school, Course.semester as semester,
User.name as studentName, User.username as studentUsername,
User.phone as studentPhone, User.email as studentEmail, User.avatar as studentAvatar
from Learn
left join Course on Learn.course_id = Course.id
left join User on Learn.user_id = User.id

     and id= #{id}
     and user_id= #{userId}
     and course_id= #{courseId}

SELECT * FROM Learn
WHERE course_id = #{courseId}
AND (course_status IS NULL OR course_status = 'ACTIVE')

